import {SignedDataType, Buffer, BufferLayout} from '@luma.gl/core';
import {BufferTransform} from '@luma.gl/engine';
import {GLSLShaderAssembler, type ShaderModule} from '@luma.gl/shadertools';
import {GPUDataEvaluator} from '../../../operation/gpu-data-evaluator';
import {bufferPool} from '../../../utils/buffer-pool';
import {
  getAttributeType,
  getVertexFormat,
  getZeroLiteral,
  type QualifiedVectorSize
} from './helper';

const GPGPU_OPERATION_STATS = 'GPGPU Operation Counts';
const TRANSFORM_RUNS = 'Transform Runs';
const GPGPU_SHADER_ASSEMBLER = new GLSLShaderAssembler();

export function runRowTransform({
  module,
  elementWise = false,
  expression,
  inputs,
  output,
  operationType = output.type,
  outputBuffer
}: {
  module: ShaderModule;
  elementWise?: boolean;
  expression?: (laneIndex: number) => string;
  inputs: {[name: string]: GPUDataEvaluator} | GPUDataEvaluator[];
  output: GPUDataEvaluator;
  /** If specified, coerce all parameters to operation to this type.
   * Default to output's data type.
   */
  operationType?: SignedDataType;
  outputBuffer: Buffer;
}): void {
  const device = outputBuffer.device;
  const outputModule = getOutputModule('result', output.type, output.size, output.normalized);
  const modules: ShaderModule[] = [module, outputModule];
  const bufferLayout: BufferLayout[] = [];
  const inputBuffers: {[name: string]: Buffer} = {};
  const outputType = getAttributeType(output.type, 1, output.normalized);
  const castToType = getAttributeType(operationType, 1, output.normalized);
  let inputBlock = '';

  let placeholderBuffer: Buffer | null = null;

  const defines: Record<string, string> = {
    TYPE: castToType,
    RESULT_LEN: output.size.toString()
  };
  const inputEntries = getInputEntries(inputs);

  for (const [name, input] of inputEntries) {
    modules.push(getInputModule(name, input.type, input.size, input.normalized, operationType));
    bufferLayout.push(getInputBufferLayout(name, input));
    if (input instanceof GPUDataEvaluator) {
      inputBuffers[name] = input.buffer;
    } else {
      placeholderBuffer =
        placeholderBuffer || bufferPool.createOrReuse(device, outputBuffer.byteLength);
      inputBuffers[name] = placeholderBuffer;
    }

    inputBlock += `TYPE ${name}[${input.size}]; get_${name}(${name});\n`;
    defines[`${name.toUpperCase()}_LEN`] = input.size.toString();
  }

  let computeResult = '';

  if (expression) {
    for (let i = 0; i < output.size; i++) {
      computeResult += `result[${i}]=${expression(i)};\n`;
    }
  } else if (elementWise) {
    for (let i = 0; i < output.size; i++) {
      const zero = getZeroLiteral(castToType);
      const elementInputs = inputEntries.map(([name, input]) => {
        if (i < input.size) return `${name}[${i}]`;
        return zero;
      });
      computeResult += `result[${i}]=${module.name}(${elementInputs.join(', ')});\n`;
    }
  } else {
    computeResult = `${module.name}(${inputEntries.map(([name]) => name).join(', ')}, result);`;
  }

  const vertexShader = /* glsl */ `\
#version 300 es

void main() {
${inputBlock}
${outputType} result[${output.size}];
${computeResult}
set_result(result);
}
  `;

  const transform = new BufferTransform(device, {
    vs: vertexShader,
    shaderAssembler: GPGPU_SHADER_ASSEMBLER,
    // @ts-expect-error defines can only be boolean?
    defines,
    modules,
    bufferLayout,
    vertexCount: 1,
    instanceCount: output.length,
    attributes: inputBuffers,
    feedbackBufferMode: 'interleaved',
    outputs: outputModule.varyings
  });

  device.statsManager.getStats(GPGPU_OPERATION_STATS).get(TRANSFORM_RUNS).incrementCount();
  transform.run({
    inputBuffers: inputBuffers,
    outputBuffers: {
      [outputModule.varyings[0]]:
        output.offset === 0
          ? outputBuffer
          : {buffer: outputBuffer, byteOffset: output.offset, byteLength: output.byteLength}
    }
  });
  if (placeholderBuffer) {
    bufferPool.recycle(placeholderBuffer);
  }
}

function getInputEntries(
  inputs: {[name: string]: GPUDataEvaluator} | GPUDataEvaluator[]
): [string, GPUDataEvaluator][] {
  return Array.isArray(inputs)
    ? inputs.map((input, index) => [`x${index}`, input])
    : Object.entries(inputs);
}

export function getInputModule(
  name: string,
  inType: SignedDataType,
  inSize: number,
  normalized: boolean = false,
  outType: SignedDataType = inType
): ShaderModule {
  let attributeBlock = '';
  let funcBlock = '';

  for (let i = 0; i < inSize; i += 4) {
    const size = Math.min(inSize - i, 4) as QualifiedVectorSize;
    const inDataType = getAttributeType(inType, size, normalized);

    attributeBlock += `in ${inDataType} a${name}_${i};\n`;

    for (let j = 0; j < size; j++) {
      let element = `a${name}_${i}`;
      if (size > 1) {
        element = `${element}[${j}]`;
      }
      if (normalized || inType !== outType) {
        element = `TYPE(${element})`;
      }
      funcBlock += `v[${i + j}]=${element};\n`;
    }
  }

  const vs = `
${attributeBlock}
void get_${name}(out TYPE v[${inSize}]) {
  ${funcBlock}
}
`;

  return {
    name,
    vs
  } as ShaderModule;
}

export function getInputBufferLayout(name: string, source: GPUDataEvaluator): BufferLayout {
  const bufferLayout: BufferLayout = {
    name,
    stepMode: source.isConstant ? 'vertex' : 'instance',
    byteStride: source.stride,
    attributes: []
  };
  for (let i = 0; i < source.size; i += 4) {
    const size = Math.min(source.size - i, 4) as QualifiedVectorSize;
    bufferLayout.attributes!.push({
      attribute: `a${name}_${i}`,
      format: getVertexFormat(source.type, size, source.normalized),
      byteOffset: source.offset + source.ValueType.BYTES_PER_ELEMENT * i
    });
  }
  return bufferLayout;
}

export function getOutputModule(
  name: string,
  outType: SignedDataType,
  outSize: number,
  normalized: boolean = false
): ShaderModule & {varyings: string[]} {
  const varyings: string[] = [];
  const outputType = getAttributeType(outType, 1, normalized);
  let varyingBlock = '';
  let functionBlock = '';

  for (let index = 0; index < outSize; index += 4) {
    const size = Math.min(outSize - index, 4) as QualifiedVectorSize;
    const outDataType = getAttributeType(outType, size, normalized);
    varyings.push(`${name}_${index}`);
    varyingBlock += `flat out ${outDataType} ${name}_${index};\n`;
    const vectorIndices = Array.from({length: size}, (_, offset) => index + offset);
    functionBlock += `${name}_${index} = ${outDataType}(${vectorIndices.map(vectorIndex => `v[${vectorIndex}]`).join(',')});\n`;
  }

  return {
    name,
    varyings,
    vs: `
${varyingBlock}
void set_${name}(in ${outputType} v[${outSize}]) {
  ${functionBlock}
}
`
  } as ShaderModule & {varyings: string[]};
}
